// Valida la respuesta de /api/tournament-recaps/context y deja lo que usan los nodos siguientes.
const res = $json;
if (!res || res.success !== true || !res.data || !res.data.tournament) {
  throw new Error('Prepare Agent Input: la respuesta de /api/tournament-recaps/context no trae data.tournament.');
}
return {
  json: {
    tournamentId: String(res.data.tournament.id),
    tournamentName: res.data.tournament.name,
    contextVersion: res.contextVersion,
    detail: res.detail,
    meta: res.meta,
    data: res.data,
  },
};

