      "type": "string",
      "minLength": 1,
      "maxLength": 500,
      "description": "Resumen de 2 o 3 oraciones en texto plano, hasta 500 caracteres."
    },
    "recap": {
      "type": "string",
      "minLength": 1,
      "description": "Crónica en Markdown, 600 a 900 palabras, con los títulos ## del contrato y sin título de nivel 1."
    }
  },
  "required": [
    "headline",
    "summary",
    "recap"
  ],
  "additionalProperties": false
}

