// Verifica la salida del modelo antes de guardar. Junta todos los problemas y lanza un solo error.
const ctx = $('Prepare Agent Input').item.json;
const data = ctx.data;
let out = $json.output !== undefined ? $json.output : ($json.text !== undefined ? $json.text : $json.response);
if (typeof out === 'string') {
  try { out = JSON.parse(out); } catch (e) { throw new Error('Verify Recap [' + ctx.tournamentName + ']: la salida del modelo no es un objeto JSON.'); }
}
out = out || {};

const errors = [];
const norm = (s) => String(s == null ? '' : s).normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/\s+/g, ' ').trim();
const asText = (v, name) => { if (typeof v !== 'string') { errors.push(name + ' no es texto'); return ''; } return v.trim(); };
const headline = asText(out.headline, 'headline');
const summary = asText(out.summary, 'summary');
const recap = asText(out.recap, 'recap');

// 1) Longitudes
if (headline.length < 1 || headline.length > 140) errors.push('headline de ' + headline.length + ' caracteres (1 a 140)');
if (summary.length < 1 || summary.length > 500) errors.push('summary de ' + summary.length + ' caracteres (1 a 500)');
const words = recap.split(/\s+/).filter(Boolean).length;
if (words < 450 || words > 1100) errors.push('recap de ' + words + ' palabras (450 a 1100)');

// 2) Secciones ## según las etapas del formato (mismo criterio que el BE)
const stages = (data.tournament.rules && data.tournament.rules.stages) || [];
const headings = recap.split(/\r?\n/).map((l) => /^##(?!#)\s*(.+?)\s*#*\s*$/.exec(l)).filter(Boolean).map((m) => norm(m[1]));
const required = [['El campeón']];
if (stages.includes('regular')) required.push(['Fase regular', 'Fase de grupos']);
if (stages.includes('playin')) required.push(['Play-in']);
if (stages.includes('playoff')) required.push(['Playoffs']);
required.push(['En la historia']);
for (const alts of required) {
  if (!alts.some((t) => headings.some((h) => h.startsWith(norm(t))))) errors.push('falta la sección ## ' + alts.join(' / '));
}
if (headings.length && !headings[0].startsWith('el campeon')) errors.push('la primera sección debe ser El campeón');
if (headings.length && !headings[headings.length - 1].startsWith('en la historia')) errors.push('la última sección debe ser En la historia');

// 3) Campeón y subcampeón por nombre (jugador y equipo)
const text = norm(recap);
const r = data.result || {};
const names = [
  ['campeón (jugador)', r.champion && r.champion.player && r.champion.player.name],
  ['campeón (equipo)', r.champion && r.champion.team && r.champion.team.name],
  ['subcampeón (jugador)', r.runnerUp && r.runnerUp.player && r.runnerUp.player.name],
  ['subcampeón (equipo)', r.runnerUp && r.runnerUp.team && r.runnerUp.team.name],
];
for (const [label, name] of names) {
  if (name && !text.includes(norm(name))) errors.push('no nombra al ' + label + ': ' + name);
}

// 4) Reglas de forma y de voz
if (/\bmaxi\b/i.test(recap)) errors.push('dice "Maxi" (es "Max")');
if (/^#\s/m.test(recap)) errors.push('tiene un título de nivel 1');
if (recap.includes('```')) errors.push('tiene un bloque de código');
if (/podria deberse|quizas|tal vez/.test(text)) errors.push('usa una frase de duda prohibida');
const codes = recap.match(/\b(single_match|expected_points|golden_goal|same_player_pick|walkover|advanceP1|advanceP2|p1Win|p2Win|ratingDelta|dataQuality|titleContext|matchSeqs?|isNewAllTimePeak|bestCumulativeDelta|worstCumulativeDelta|globalRatingBeforeFirstMatch|globalRatingAfterLastMatch|globalPeakRating)\b/gi);
if (codes) errors.push('muestra códigos internos: ' + Array.from(new Set(codes)).join(', '));

// 5) Porcentajes: todos tienen que salir del contexto
const nums = (JSON.stringify(data).match(/-?\d+(?:\.\d+)?/g) || []).map(Number);
const key = (x) => Math.round(x * 10) / 10;
const allowed = new Set();
for (const v of nums) { allowed.add(key(v)); allowed.add(key(Math.round(v))); allowed.add(key(Math.round(v * 100))); allowed.add(key(Math.floor(v * 100))); allowed.add(key(Math.ceil(v * 100))); }
for (const m of recap.matchAll(/(\d+(?:[.,]\d+)?)\s?%/g)) {
  const n = Number(m[1].replace(',', '.'));
  if (!allowed.has(key(n))) errors.push('el porcentaje ' + m[0] + ' no sale del contexto');
}
if (/(serie|global|agregado)[^.\n]{0,80}\d+\s?%|\d+\s?%[^.\n]{0,80}(la serie|global|agregado)|\d+\s?%[^.\n]{0,60}(de ser campeon|de salir campeon|el titulo)/.test(text)) errors.push('da una probabilidad de serie, global o título');

// 6) Sorpresas solo si el contexto las marca
const hasUpset = (data.matches || []).some((m) => m.upset === true) || (data.facts || []).some((f) => f.type === 'biggest_upset' || f.type === 'upsets');
if (!hasUpset && /batacazo/.test(text)) errors.push('habla de batacazo sin partidos con upset');

if (errors.length) throw new Error('Verify Recap [' + ctx.tournamentName + ']: ' + errors.join(' | '));
return { json: { tournamentId: ctx.tournamentId, headline, summary, recap, wordCount: words } };
